pub struct AveragedCollection {
    list: Vec<i32>,
    average: f64,
}

impl AveragedCollection {
    pub fn new() -> Self {
        AveragedCollection { list: vec![], average: 0.0 }
    }

    pub fn add(&mut self, value: i32) {
        self.list.push(value);
        self.update_average();
    }

    pub fn remove(&mut self) -> Option<i32> {
        let result = self.list.pop();
        match result {
            Some(value) => {
                self.update_average();
                Some(value)
            }
            None => None,
        }
    }

    pub fn average(&self) -> f64 {
        self.average
    }

    fn update_average(&mut self) {
        let total: i32 = self.list.iter().sum();
        self.average = total as f64 / self.list.len() as f64;
    }
}

fn main() {
    let mut c = AveragedCollection::new();
    c.add(3);
    c.add(4);
    c.add(8);
    println!("average = {}", c.average());
    c.remove();
    println!("average = {}", c.average());
}

// composition: an Employee *has* a Person instead of *being* one
struct Person {
    name: String,
}

struct Employee {
    person: Person,
    salary: u32,
}

trait Describe {
    fn name(&self) -> &str;

    // shared behavior via a default method
    fn describe(&self) -> String {
        format!("This is {}", self.name())
    }
}

impl Describe for Person {
    fn name(&self) -> &str {
        &self.name
    }
}

impl Describe for Employee {
    fn name(&self) -> &str {
        self.person.name() // delegate to the inner value
    }

    fn describe(&self) -> String {
        format!("{} (salary {})", self.person.describe(), self.salary)
    }
}

fn main() {
    let p = Person { name: String::from("Ada") };
    let e = Employee { person: Person { name: String::from("Grace") }, salary: 100 };
    println!("{}", p.describe());
    println!("{}", e.describe());
}
